        let temp_dir = tempfile::tempdir()?;
        let path = temp_dir.path().to_path_buf();

        if fixture_path.exists() {
            let _ = std::process::Command::new("cp")
                .arg("-r")
                .arg(fixture_path)
                .arg(&path)
                .output()?;
        }

