use lumen_model::transcript::{CanonicalTranscript, ExecutionTiming, OrchestratorKind};
use lumen_model::turn::{CanonicalTurn, TurnRole, TurnTokenUsage};
use lumen_model::TokenEconomics;
use prism_grader::matrix::{MatrixResultDatum, MetricDifferential};
use prism_grader::AssertionResult;
use smallvec::smallvec;

#[test]
fn test_matrix_result_datum_and_differential() {
    let baseline_transcript = CanonicalTranscript {
        session_id: CompactString::new("task-1"),
        parent_session_id: None,
        orchestrator: OrchestratorKind::ClaudeCode,
        model_family: CompactString::new("claude-3-5-sonnet-20241022"),
        timing: ExecutionTiming {
            started_at: Utc::now(),
            ended_at: Utc::now(),
            wall_duration_ms: 10000,
            active_duration_ms: 10000,
            idle_duration_ms: 0,
            idle_gap_count: 0,
        },
        economics: TokenEconomics::calculate(1000, 300, 500, 200, "claude-3-5-sonnet-20241022"),
        turns: vec![
            CanonicalTurn {
                turn_index: 0,
                role: TurnRole::Assistant,
                timestamp: Utc::now(),
                latency_ms: 4000,
                text: None,
                tool_calls: smallvec![],
                tool_results: smallvec![],
                usage: Some(TurnTokenUsage {
                    input_tokens: 500,
                    output_tokens: 150,
                    cache_creation_tokens: 250,
                    cache_read_tokens: 100,
                }),
            },
            CanonicalTurn {
                turn_index: 1,
                role: TurnRole::Assistant,
                timestamp: Utc::now(),
                latency_ms: 6000,
                text: None,
                tool_calls: smallvec![],
                tool_results: smallvec![],
                usage: Some(TurnTokenUsage {
                    input_tokens: 500,
                    output_tokens: 150,
                    cache_creation_tokens: 250,
                    cache_read_tokens: 100,
                }),
            },
        ],
        subagents: vec![],
        extracted_schemas: smallvec![],
        detected_anomalies: smallvec![],
    };

    let baseline_assertions = vec![
        AssertionResult {
            name: CompactString::new("test_suite"),
            passed: true,
            message: "ok".into(),
            latency_ms: 100,
        },
        AssertionResult {
            name: CompactString::new("cache_health"),
            passed: false,
            message: "low cache hit".into(),
            latency_ms: 50,
        },
    ];

    let baseline_datum = MatrixResultDatum::from_execution(
        "baseline-sonnet",
        "claude-3-5-sonnet",
        "claude-cli",
        "raw-prompt",
        &baseline_transcript,
        &baseline_assertions,
    );

    assert_eq!(baseline_datum.pass_rate, 50.0);
    assert_eq!(baseline_datum.total_wall_time_ms, 10000);
    assert_eq!(baseline_datum.turn_count, 2);

    // Optimized variant
    let opt_transcript = CanonicalTranscript {
        session_id: CompactString::new("task-1"),
        parent_session_id: None,
        orchestrator: OrchestratorKind::ClaudeCode,
        model_family: CompactString::new("claude-3-5-sonnet-20241022"),
        timing: ExecutionTiming {
            started_at: Utc::now(),
            ended_at: Utc::now(),
            wall_duration_ms: 2000,
            active_duration_ms: 2000,
            idle_duration_ms: 0,
            idle_gap_count: 0,
        },
        economics: TokenEconomics::calculate(100, 150, 100, 1500, "claude-3-5-sonnet-20241022"),
        turns: vec![
            CanonicalTurn {
                turn_index: 0,
                role: TurnRole::Assistant,
                timestamp: Utc::now(),
                latency_ms: 2000,
                text: None,
                tool_calls: smallvec![],
                tool_results: smallvec![],
                usage: Some(TurnTokenUsage {
                    input_tokens: 100,
                    output_tokens: 150,
                    cache_creation_tokens: 100,
                    cache_read_tokens: 1500,
                }),
            },
        ],
        subagents: vec![],
        extracted_schemas: smallvec![],
        detected_anomalies: smallvec![],
    };

    let opt_assertions = vec![
        AssertionResult {
            name: CompactString::new("test_suite"),
            passed: true,
            message: "ok".into(),
            latency_ms: 100,
        },
        AssertionResult {
            name: CompactString::new("cache_health"),
            passed: true,
            message: "high cache hit".into(),
            latency_ms: 50,
        },
    ];

    let opt_datum = MatrixResultDatum::from_execution(
        "opt-sonnet",
        "claude-3-5-sonnet",
        "claude-cli",
        "bug-hunter-rust",
        &opt_transcript,
        &opt_assertions,
    );

    assert_eq!(opt_datum.pass_rate, 100.0);
    assert_eq!(opt_datum.turn_count, 1);
    assert_eq!(opt_datum.total_wall_time_ms, 2000);

    // Compute differential
    let diff = MetricDifferential::compute(&opt_datum, &baseline_datum);
    assert_eq!(diff.delta_pass_rate_pct, 50.0);
    assert!(diff.delta_cost_pct < 0.0); // Cost reduced
    assert_eq!(diff.delta_turns_pct, -50.0); // 1 vs 2 -> -50%
    assert!(diff.delta_cache_hit_pct > 0.0); // Cache hit ratio increased
    assert_eq!(diff.delta_wall_time_pct, -80.0); // 2000 vs 10000 -> -80%
}
