1	use compact_str::CompactString;
2	use lumen_model::{CanonicalTurn, ToolIntent};
3	use serde::{Deserialize, Serialize};
4	
5	use crate::traits::EntryAccumulator;
6	
7	#[derive(Debug, Clone, Serialize, Deserialize)]
8	pub struct CircuitStallEvent {
9	    pub agent_pair: CompactString,
10	    pub observed_rounds: usize,
11	    pub turn_index: usize,
12	}
13	
14	#[derive(Debug, Clone, Serialize, Deserialize, Default)]
15	pub struct CircuitBreakerReport {
16	    pub max_observed_rounds: usize,
17	    pub stalls: Vec<CircuitStallEvent>,
18	    pub tripped: bool,
19	}
20	
21	#[derive(Debug, Default, Clone)]
22	pub struct CircuitBreakerAccumulator {
23	    pub current_agent_pair: Option<CompactString>,
24	    pub consecutive_rounds: usize,
25	    pub max_observed_rounds: usize,
26	    pub stalls: Vec<CircuitStallEvent>,
27	}
28	
29	impl EntryAccumulator for CircuitBreakerAccumulator {
30	    type Output = CircuitBreakerReport;
31	
32	    fn update(&mut self, entry: &CanonicalTurn) {
33	        for call in &entry.tool_calls {
34	            if let ToolIntent::SubagentSpawn { agent_type, .. } = &call.intent {
35	                let pair = CompactString::new(format!("parent->{agent_type}"));
36	
37	                if self.current_agent_pair.as_ref() == Some(&pair) {
38	                    self.consecutive_rounds += 1;
39	                } else {
40	                    self.current_agent_pair = Some(pair.clone());
41	                    self.consecutive_rounds = 1;
42	                }
43	
44	                self.max_observed_rounds = self.max_observed_rounds.max(self.consecutive_rounds);
45	
46	                if self.consecutive_rounds > 2 {
